const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const cf=($('Resolve Base').first().json.fields)||{};
const att=Array.isArray(f['Attachment'])?f['Attachment']:[];
if(!att.length){ throw new Error('Launch record '+rec.id+' has no Attachment CSV.'); }
const rawTid=((f['Table ID']||f['Target']||'')+'').trim();
const m=rawTid.match(/tbl[A-Za-z0-9]{14}/);
return [{ json: {
  'Clayroots Base ID': ((cf['Clayroots Base ID']||'')+'').trim(),
  'Build name': ((f['Build name']||'')+'').trim(),
  'Existing Table ID': m?m[0]:rawTid,
  'Tag': ((f['Tag']||'')+'').trim(),
  'Seniority levels (default net pre-ticked; untick to narrow)': f['Seniority']||'',
  'Target departments (tick to narrow; ALL = every department)': f['Departments']||'',
  'Contacts per company': parseInt(f['Contacts per company'],10)||5,
  'Contact location': f['Country']||'',
  '_csvName': (att[0]&&att[0].filename)||'launch.csv',
  '_launchRecordId': rec.id,
  'submittedAt': new Date().toISOString()
} }];

const items=$input.all();
const bin=(items[0]&&items[0].binary)||{};
const data=bin.data||Object.values(bin)[0];
if(!data){ throw new Error('Download CSV returned no binary data.'); }
return [{ json: $('Launch Params').first().json, binary: { Storeleads_domains_CSV: data } }];

const rows=$input.all().map(i=>i.json);
if(!rows.length){ throw new Error('CSV parse returned no rows.'); }
const headers=Object.keys(rows[0]||{});
const domKey=headers.find(h=>String(h).trim().toLowerCase()==='domain');
if(!domKey){ throw new Error('No Domain column found in CSV. Headers found: '+headers.join(', ')); }
const COLS=['Company','company_clean','Industry Groups','Business Model','MX Provider','Employees','City','State','Country','Description','Plan','Revenue Est Monthly','Store Age Years','Product Count','App Spend Mo','Key Apps','Tech Stack','Trustpilot Rating','Trustpilot Reviews','Migrated From','Social Followers','Growth 90d','Features'];
const have=new Set(COLS.filter(c=>headers.includes(c)));
const domains=[]; const cmap={}; const seen=new Set();
for(const r of rows){
  const d=String(r[domKey]==null?'':r[domKey]).trim().toLowerCase();
  if(!d||seen.has(d))continue;
  seen.add(d); domains.push(d);
  const co={};
  for(const c of COLS){ co[c]=have.has(c)?(r[c]==null?'':r[c]):''; }
  cmap[d]=co;
}
return [{ json: { _domains: domains, _cmap: cmap, _domain_count: domains.length, _row_count: rows.length } }];

const g = $('Launch Guard').first().json;
const t = (n) => ({ name: n, type: 'singleLineText' });
const num = (n, p) => ({ name: n, type: 'number', options: { precision: (p===undefined?0:p) } });
const sel = (n, ch) => ({ name: n, type: 'singleSelect', options: { choices: ch.map(c => ({ name: c })) } });
const SEN=['C-Suite','Founder','Owner','President','Executive','VP','Head','Director','Manager','Senior','Partner','EVP / SVP','Board / Chair','Unclassified'];
const DEP=['Executive','Engineering','Technology','R&D','Product','Data','Security','Design','Operations','Sales','Marketing','Finance','Human Resources','Customer Success','Project Management','Strategy','Legal','Supply Chain','Communications','Community & Social','Compliance & GRC'];
const EMP=['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+'];
const fields=[
  t('Name'), t('Contact Key'), t('first_name'), t('last_name'), t('Title'),
  sel('Seniority',SEN), sel('Department',DEP),
  t('Email'), t('Social'), t('Phone'), t('Connections'), t('Domain'), t('Company'),
  t('Industry Groups'), sel('Employees',EMP), t('Business Model'), t('MX Provider'), t('Description'), t('Keywords'),
  t('City'), t('State'), t('Country'), t('Zip'), t('Street'),
  t('Contact Source'), t('Plan'),
  num('Revenue Est Monthly',0), num('Store Age Years',1), num('Product Count',0), num('App Spend Mo',0),
  t('Key Apps'), t('Tech Stack'), num('Trustpilot Rating',1), num('Trustpilot Reviews',0),
  t('Migrated From'), t('Social Followers'), num('Growth 90d',0), t('Features'),
  t('Tag')
];
// Operator ruling 2026-08-12. Removed from the contract: company_clean (cleaning happens on Company
// itself), State Full (State is the only location column), Score, Similarity, Run ID.
// 'Contact Source' replaces 'Source' for record provenance; the Strip Immutable node maps the
// formatter's Source key onto it at the write boundary. 'Email Source' (waterfall tier) is owned
// by the verification lane, which creates it on first touch.
const formulaFields = [ { name: 'Build Date', type: 'formula', options: { formula: 'CREATED_TIME()' } } ];
const desiredName = (g.buildName || 'List') + ' - Contacts';
return [{ json: { mode: g.mode, existingTableId: g.existingTableId, buildNameIgnored: !!g.buildNameIgnored, desiredName, fields, formulaFields } }];

const j = $('AT Create Table').first().json || {};
const baseId = (($('Contacts Launch').first().json['Clayroots Base ID'])||'').trim();
if (!j.id) { throw new Error('Airtable contacts-table creation failed in base ' + baseId + ': ' + JSON.stringify(j).slice(0,400)); }
const fld = $('AT Add Rank Formula').first().json || {};
if (!fld.id) { throw new Error('Seniority Rank formula field creation failed on table ' + j.id + ': ' + JSON.stringify(fld).slice(0,400)); }
return [{ json: { mode: 'create', tableId: j.id, tableName: j.name, rankFieldId: fld.id, fieldNames: (j.fields || []).map(f => f.name).concat(['Seniority Rank']) } }];

const form=$('Contacts Launch').first().json;
const pd=$('Parse Domains').first().json;
const domains=pd._domains||[];
if(!domains.length){ throw new Error('No domains to enrich after parsing the CSV.'); }
const asArr=(v)=>{ if(v===undefined||v===null||v==='')return[]; if(Array.isArray(v))return v.map(x=>String(x).trim()).filter(Boolean); return String(v).split(',').map(s=>s.trim()).filter(Boolean); };
const DEFAULT_SEN=['C-Suite','Founder','Owner','President','VP','Head','Director'];
let seniority=asArr(form['Seniority levels (default net pre-ticked; untick to narrow)']);
if(!seniority.length) seniority=DEFAULT_SEN;
const CC={'United States':'US','Israel':'IL','United Kingdom':'GB','Canada':'CA','Australia':'AU','Germany':'DE','France':'FR','Netherlands':'NL'};
const countries=asArr(form['Contact location']).map(c=>CC[c]||'').filter(Boolean);
const depsRaw=asArr(form['Target departments (tick to narrow; ALL = every department)']);
const hasAll=depsRaw.some(d=>String(d).toLowerCase()==='all');
const deps=(!depsRaw.length||hasAll)?null:depsRaw;
const perCompany=parseInt(form['Contacts per company'],10)||5;
const out=[];
for(let i=0;i<domains.length;i+=1000){
  const chunk=domains.slice(i,i+1000);
  const filters={ seniority: seniority };
  if(countries.length) filters.contact_countries=countries;
  if(deps) filters.function=deps;
  out.push({ json: { companies: chunk.map(d=>({ domain: d })), filters: filters, per_company_limit: perCompany, tier: 'full' } });
}
return out;

const items=$input.all();
const ok=items.filter(i=>i.json&&Array.isArray(i.json.results));
if(!ok.length){ const first=items[0]?JSON.stringify(items[0].json).slice(0,400):'no response'; throw new Error('Supersoniq enrich failed for all '+items.length+' chunk(s): '+first); }
return ok;

const cmap=$('Parse Domains').first().json._cmap||{};
// Generic company/domain-level carry-through. Anything the source CSV carries that is not part of
// the fixed field contract and not plumbing rides along, matching the auto-adder in Build Table
// Schema, so a new source column needs no edit here. Person-level fields stay from Supersoniq.
const CORE=new Set(['Name','Contact Key','first_name','last_name','Title','Seniority','Department','Email','Social','Phone','Connections','Domain','Company','company_clean','Industry Groups','Employees','Business Model','MX Provider','Score','Similarity','Description','Keywords','City','State','State Full','Country','Zip','Street','Source','Plan','Revenue Est Monthly','Store Age Years','Product Count','App Spend Mo','Key Apps','Tech Stack','Trustpilot Rating','Trustpilot Reviews','Migrated From','Social Followers','Growth 90d','Features','Seniority Rank']);
const XSKIP=new Set(['domain','company_domain','Verified','segment','query_name','ingested_at','RankInCompany','Run ID','Build Date','Tag','public_emails_clean','Created']);
const xmap={};
for(const r of $('Read CSV').all().map(i=>i.json)){
  const d=String(r.Domain||r.domain||r.company_domain||'').trim().toLowerCase();
  if(!d)continue;
  const x=xmap[d]||(xmap[d]={});
  for(const k of Object.keys(r)){ if(CORE.has(k)||XSKIP.has(k))continue; const v=r[k]; if((x[k]===undefined||x[k]==='')&&v!==undefined&&v!==null&&String(v).trim()!=='')x[k]=String(v).trim(); }
}
const runId=String($execution.id);
const tag=((($('Contacts Launch').first().json['Tag'])||'')+'').trim();
const _st=($('Config').first().json||{}).startedAt;
let buildDate='';
try{ buildDate=DateTime.fromISO(String(_st)).toFormat('yyyy-MM-dd'); }catch(e){ buildDate=''; }
if(!buildDate||buildDate==='Invalid DateTime'){ buildDate=$now.toFormat('yyyy-MM-dd'); }
const cap=(s)=>s?s.charAt(0).toUpperCase()+s.slice(1).toLowerCase():'';
const cleanFirst=(full)=>{ if(!full)return''; const tok=String(full).split(',')[0].trim().split(/\s+/)[0]||''; return cap(tok.replace(/[^A-Za-z'\-]/g,'')); };
const cleanLast=(full)=>{ if(!full)return''; const parts=String(full).split(',')[0].trim().split(/\s+/); if(parts.length<2)return''; return parts.slice(1).map(p=>cap(p.replace(/[^A-Za-z'\-]/g,''))).filter(Boolean).join(' '); };
const cleanCompany=(nm)=>{if(!nm)return'';const orig=String(nm).trim();let c=orig;
const GEN=new Set(['home','welcome','shop','store','about','about us','products','index','page','contact','contact us','blog','news']);
const isGen=(s)=>GEN.has(String(s).trim().toLowerCase());
const pick=(a)=>{for(const p of a){if(p&&String(p).trim()&&!isGen(p))return String(p).trim();}return null;};
c=c.replace(/^welcome to\s+/i,'').trim();
const pp=c.split(' | '); if(pp.length>1){const s=pick(pp); if(s===null) return orig; c=s;}
for(let i=0;i<2;i++){const d=c.search(/\s[-–—]\s/); if(d<3) break; const head=c.slice(0,d).trim(); const tail=c.slice(d).replace(/^\s[-–—]\s/,'').trim(); const s=pick([head,tail]); if(s===null) return orig; c=s;}
if(/^[A-Za-z0-9][A-Za-z0-9-]*(\.[A-Za-z]{2,})+$/.test(c)) c=c.replace(/(\.[A-Za-z]{2,})+$/,'');
c=c.replace(/[®™]/g,'');
for(let i=0;i<2;i++){c=c.replace(/[,\s]+(inc|llc|l\.l\.c\.|ltd|limited|corp|corporation|co|company|gmbh|plc|llp|lp|pllc|pc)\.?$/i,'').trim();}
c=c.replace(/,+$/,'').trim();
const hasUp=/\p{Lu}/u.test(c), hasLow=/\p{Ll}/u.test(c);
if(hasUp!==hasLow){const parts=c.split(/(\s+)/); const words=parts.filter(t=>/\S/.test(t)); const MINOR=new Set(['of','and','the','for','to','in','on','at','by','a','an']);
if(!(hasUp&&words.length===1&&c.length<=4)){let wi=-1; c=parts.map(t=>{if(!/\S/.test(t))return t; wi++; const lw=t.toLowerCase(); return (wi>0&&MINOR.has(lw))?lw:lw.replace(/\p{L}/u,(ch)=>ch.toUpperCase());}).join('');}}
return c;};
const band=(n)=>{ n=Number(n); if(!Number.isFinite(n)||n<=0)return''; if(n<=10)return'1-10'; if(n<=50)return'11-50'; if(n<=200)return'51-200'; if(n<=500)return'201-500'; if(n<=1000)return'501-1000'; if(n<=5000)return'1001-5000'; if(n<=10000)return'5001-10000'; return'10001+'; };
const STATES={AL:'Alabama',AK:'Alaska',AZ:'Arizona',AR:'Arkansas',CA:'California',CO:'Colorado',CT:'Connecticut',DE:'Delaware',FL:'Florida',GA:'Georgia',HI:'Hawaii',ID:'Idaho',IL:'Illinois',IN:'Indiana',IA:'Iowa',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',ME:'Maine',MD:'Maryland',MA:'Massachusetts',MI:'Michigan',MN:'Minnesota',MS:'Mississippi',MO:'Missouri',MT:'Montana',NE:'Nebraska',NV:'Nevada',NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NY:'New York',NC:'North Carolina',ND:'North Dakota',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',TN:'Tennessee',TX:'Texas',UT:'Utah',VT:'Vermont',VA:'Virginia',WA:'Washington',WV:'West Virginia',WI:'Wisconsin',WY:'Wyoming',DC:'District of Columbia',PR:'Puerto Rico',ON:'Ontario',QC:'Quebec',BC:'British Columbia',AB:'Alberta',MB:'Manitoba',SK:'Saskatchewan',NS:'Nova Scotia',NB:'New Brunswick'};
const stateFull=(s)=>{ const v=String(s||'').trim(); if(!v)return''; const up=v.toUpperCase(); if(STATES[up])return STATES[up]; return v.split(/\s+/).map(cap).join(' '); };
const numOr=(v)=>{ if(v===null||v===undefined||String(v).trim()==='')return''; const n=Number(v); return Number.isFinite(n)?n:''; };
const out=[];
let skipped=0;
for(const it of $input.all()){
  const resp=it.json||{};
  const results=Array.isArray(resp.results)?resp.results:[];
  for(const r of results){
    const contacts=Array.isArray(r.contacts)?r.contacts:[];
    for(const ct of contacts){
      const domain=String(ct.company_domain||'').trim().toLowerCase();
      const co=cmap[domain]||{};
      const extras=xmap[domain]||{};
      const full=((String(ct.first_name||'')+' '+String(ct.last_name||'')).trim())||String(ct.full_name||'');
      const first=cleanFirst(full); const last=cleanLast(full);
      const key=(first.toLowerCase()+last.toLowerCase()+domain).trim();
      if(!key){ skipped++; continue; }
      const coName=cleanCompany(co.Company||String(ct.company_name||''));
      out.push({ json: {
        ...extras,
        'Contact Key': key,
        Name: full, first_name: first, last_name: last,
        Title: String(ct.job_title||''), Seniority: String(ct.seniority||''), Department: String(ct.function||''),
        Email: String(ct.email||''), Social: String(ct.linkedin_url||''),
        Phone:'', Connections:'',
        Domain: domain, Company: coName, company_clean: coName,
        'Industry Groups': co['Industry Groups']||'', Employees: band(co.Employees),
        'Business Model': co['Business Model']||'', 'MX Provider': co['MX Provider']||'',
        Score:'', Similarity:'', Description: co.Description||'', Keywords:'',
        City: co.City||'', State: co.State||'', 'State Full': stateFull(co.State), Country: co.Country||'',
        Zip:'', Street:'', Source:'Supersoniq', 'Run ID': runId, 'Build Date': buildDate, Tag: tag,
        Plan: co.Plan||'',
        'Revenue Est Monthly': numOr(co['Revenue Est Monthly']),
        'Store Age Years': numOr(co['Store Age Years']),
        'Product Count': numOr(co['Product Count']),
        'App Spend Mo': numOr(co['App Spend Mo']),
        'Key Apps': co['Key Apps']||'', 'Tech Stack': co['Tech Stack']||'',
        'Trustpilot Rating': numOr(co['Trustpilot Rating']),
        'Trustpilot Reviews': numOr(co['Trustpilot Reviews']),
        'Migrated From': co['Migrated From']||'', 'Social Followers': co['Social Followers']||'',
        'Growth 90d': numOr(co['Growth 90d']), Features: co.Features||''
      }});
    }
  }
}
const sd=$getWorkflowStaticData('global');
sd.contactsSkipped=skipped;
sd.contactsWritten=out.length;
if(!out.length){ throw new Error('Supersoniq returned no usable contacts for '+($('Parse Domains').first().json._domain_count)+' domain(s). Rows skipped for an empty Contact Key: '+skipped+'.'); }
return out;

const form=$('Contacts Launch').first().json;
const started=form.submittedAt||$('Config').first().json.startedAt;
const pd=$('Parse Domains').first().json;
const domainsIn=pd._domain_count||0;
const chunks=$('SQ Guard').all().map(i=>i.json);
let failedChunks=0; try{ failedChunks=Math.max(0,$('SQ Enrich').all().length-chunks.length); }catch(e){}
let companiesMatched=0, credits=0;
const domainsWith=new Set();
for(const c of chunks){
  const rs=Array.isArray(c.results)?c.results:[];
  companiesMatched+=rs.length;
  for(const r of rs){ const cts=Array.isArray(r.contacts)?r.contacts:[]; for(const ct of cts){ const d=String(ct.company_domain||'').trim().toLowerCase(); if(d)domainsWith.add(d); } }
  const cr=c.credits_used!=null?c.credits_used:(c.credits!=null?c.credits:((c.usage&&c.usage.credits_used)||0));
  credits+=Number(cr)||0;
}
const delivered=$('Format Supersoniq').all().length;
const sd=$getWorkflowStaticData('global');
const skipped=Number(sd.contactsSkipped)||0;
const zeroDomains=Math.max(0,domainsIn-domainsWith.size);
const overflowCount=Number(sd.overflowCount)||0;
const overflowUrl=sd.overflowUrl||'';
const overflowError=sd.overflowError||'';
let clientRec=[]; try{ const rc=$('Resolve Client').first().json; if(rc&&rc.id)clientRec=[rc.id]; }catch(e){}
const g=$('Contacts Table Guard').first().json||{};
const tableName=g.tableName||'';
const tableId=g.tableId||'';
const modeTxt=(g.mode==='append')?'appended to an existing table':'created a new table';
const fc=(g.fieldsCreated&&g.fieldsCreated.length)?g.fieldsCreated.join(', '):'none';
const tag=((form['Tag']||'')+'').trim();
let dur=0; try{ if(started)dur=Math.max(0,Math.round((Date.now()-new Date(started).getTime())/1000)); }catch(e){}
const trig=form._launchRecordId?('record-launched by '+form._launchRecordId):'form-launched';
const errors=(g.createdFieldError?1:0)+failedChunks+(overflowError?1:0);
const fmt=v=>Number(v||0).toLocaleString('en-US');
const parts=[];
parts.push('**'+fmt(domainsIn)+' domains in, '+fmt(delivered)+' contacts delivered**');
parts.push('**Tag:** '+(tag||'none'));
parts.push('**Supersoniq**\n- **Companies matched:** '+fmt(companiesMatched)+'\n- **Contacts delivered:** '+fmt(delivered)+'\n- **Credits used:** '+fmt(credits)+'\n- **Domains with zero contacts:** '+fmt(zeroDomains)+'\n- **Rows skipped (empty Contact Key):** '+fmt(skipped));
parts.push('**Table:** '+modeTxt+', '+tableName+' ('+tableId+')\n**Fields created:** '+fc);
if(overflowUrl){ parts.push('**Leads Overflow report:** '+fmt(overflowCount)+' domains without contacts\n'+overflowUrl); }
else if(overflowCount>0&&!overflowError){ parts.push('**Leads Overflow report:** '+fmt(overflowCount)+' domains without contacts, not uploaded.'); }
const warns=[];
if(failedChunks){ warns.push('- '+failedChunks+' Supersoniq chunk(s) failed and were dropped.'); }
if(g.createdFieldError){ warns.push('- '+g.createdFieldError); }
if(g.buildNameIgnored){ warns.push('- Build name ignored: an Existing Table ID was supplied.'); }
if(overflowError){ warns.push('- '+overflowError); }
if(warns.length){ parts.push('**Warnings ('+warns.length+')**\n'+warns.join('\n')); }
parts.push('**Source:** Storeleads CSV ('+trig+')');
const log={
  'Automation': 'Storeleads Domains -> Supersoniq -> Clayroots',
  'Status': errors?'Succeeded with errors':'Succeeded',
  'Trigger': 'form',
  'Errors': errors,
  'Run at': new Date().toISOString(),
  'Target': tableName+' ('+tableId+')',
  'Records In': domainsIn,
  'Records Out': delivered,
  'Duration s': dur,
  'Description': parts.join('\n\n'),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(clientRec.length){ log['Client']=clientRec; }
return [{ json: log }];

const item = $input.first();
const form = item.json || {};
const build = ((form['Build name'] || '') + '').trim();
const tid = ((form['Existing Table ID'] || '') + '').trim();
if (!build && !tid) { throw new Error('Provide a Build name (to create a new table) or an Existing Table ID (to append to one). Nothing was pulled.'); }
if (tid && !/^tbl[A-Za-z0-9]{14}$/.test(tid)) { throw new Error('Existing Table ID "' + tid + '" is not a valid Airtable table id (expected tbl followed by 14 characters). Nothing was pulled.'); }
return [{ json: Object.assign({}, form, { buildName: build, existingTableId: tid, mode: tid ? 'append' : 'create', buildNameIgnored: !!(tid && build) }), binary: item.binary }];

const spec = $('Build Table Schema').first().json;
const baseId = (($('Contacts Launch').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT List Tables').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not read the table list for base ' + baseId + ': ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const plain = spec.fields || [];
const formulas = spec.formulaFields || [];
if (spec.mode !== 'append') {
  const taken = new Set(tables.map(t => String(t.name)));
  let name = spec.desiredName; let n = 1;
  while (taken.has(name)) { n++; name = spec.desiredName + ' (' + n + ')'; }
  return [{ json: { mode: 'create', createName: name, fields: plain, missing: [], missingNames: [], formulaNames: formulas.map(f => f.name), buildNameIgnored: false } }];
}
const target = tables.find(t => t.id === spec.existingTableId);
if (!target) { throw new Error('Table ' + spec.existingTableId + ' does not exist in base ' + baseId + '. Tables there: ' + tables.map(t => t.name).join(', ') + '. Nothing was written.'); }
if (/domains/i.test(String(target.name || ''))) { throw new Error("Refusing to write contacts into '" + target.name + "' - that table is a domains table. Nothing was written."); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const existing = new Map(targetFields.map(f => [f.name, f]));
const existingCI = new Map(targetFields.map(f => [norm(f.name), f]));
const COMPUTED = new Set(formulas.map(f => f.name));
const kind = (ty) => ty === 'number' ? 'number' : (ty === 'singleSelect' ? 'select' : (ty === 'date' ? 'date' : 'text'));
const okWith = { number: ['number'], text: ['singleLineText','multilineText','singleSelect'], select: ['singleSelect','singleLineText'], date: ['date','dateTime'] };
const contract = plain.concat(formulas);
const clashes = []; const missing = [];
for (const cf of contract) {
  if (COMPUTED.has(cf.name)) {
    const exc = existingCI.get(norm(cf.name));
    if (!exc) { missing.push(cf); continue; }
    if (exc.type !== 'formula') { throw new Error("Table '" + target.name + "' (" + target.id + ') still has a writable ' + cf.name + ' (type: ' + exc.type + '). Convert it to a CREATED_TIME() formula field before building. Nothing was written.'); }
    continue;
  }
  const ex = existing.get(cf.name);
  if (!ex) { missing.push(cf); continue; }
  if (!okWith[kind(cf.type)].includes(ex.type)) { clashes.push(cf.name + ' (type in table: ' + ex.type + ', type expected: ' + cf.type + ')'); }
}
if (clashes.length) { throw new Error("Type clash in table '" + target.name + "' (" + target.id + '): ' + clashes.join('; ') + '. Nothing was written.'); }
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, hasContactKey: existing.has('Contact Key'), fields: contract, missing, missingNames: missing.map(f => f.name), formulaNames: formulas.map(f => f.name), buildNameIgnored: !!spec.buildNameIgnored } }];

const r = $('Table Router').first().json;
let rows = [];
try { rows = $('AT Read Contacts').all().map(i => i.json || {}).filter(x => x && Object.keys(x).length > 0); } catch (e) { rows = []; }
const hasRows = rows.length > 0;
if (hasRows && !r.hasContactKey) { throw new Error("Target table '" + r.tableName + "' has rows but no Contact Key column. Appending contacts here would duplicate instead of dedupe. Nothing was written."); }
return [{ json: Object.assign({}, r, { fieldsCreated: [], targetHasRows: hasRows }) }];

const r = $('Table Router').first().json;
const baseId = (($('Contacts Launch').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT Verify Schema').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not re-read the schema of base ' + baseId + ' after creating fields: ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const target = tables.find(t => t.id === r.tableId);
if (!target) { throw new Error('Table ' + r.tableId + ' is no longer present in base ' + baseId + '. Nothing was written.'); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const have = new Set(targetFields.map(f => f.name));
const haveCI = new Set(targetFields.map(f => norm(f.name)));
const COMPUTED = new Set(r.formulaNames || []);
const present = (n) => COMPUTED.has(n) ? haveCI.has(norm(n)) : have.has(n);
const still = (r.fields || []).filter(f => !present(f.name)).map(f => f.name);
if (still.length) { throw new Error("Could not create these fields on '" + target.name + "' (" + target.id + '): ' + still.join(', ') + '. Nothing was written.'); }
const wanted = r.missingNames || [];
const created = wanted.filter(n => present(n));
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, fieldsCreated: created, buildNameIgnored: !!r.buildNameIgnored, createdFieldError: '' } }];

const j = $input.first().json || {};
if (j && j.mode === 'append') {
  if (!j.tableId) { throw new Error('Table resolution returned no table id: ' + JSON.stringify(j).slice(0,400)); }
  return [{ json: { tableId: j.tableId, tableName: j.tableName, mode: 'append', fieldsCreated: j.fieldsCreated || [], buildNameIgnored: !!j.buildNameIgnored, createdFieldError: j.createdFieldError || '' } }];
}
const ct = $('Created Table Guard').first().json || {};
const bd = $('AT Add Created Formula').first().json || {};
if (!bd.id) { throw new Error("Build Date formula field creation failed on new table '" + (ct.tableName || '') + "' (" + (ct.tableId || '') + '): ' + JSON.stringify(bd).slice(0,400) + '. Nothing was written.'); }
const fieldsCreated = (ct.fieldNames || []).slice().concat(['Build Date']);
return [{ json: { tableId: ct.tableId, tableName: ct.tableName, mode: 'create', fieldsCreated, buildNameIgnored: false, createdFieldError: '' } }];

// Write-boundary standard, Operator ruling 2026-08-12. Removes everything retired from the contract
// so the payload can never resurrect a banned column or 422 on a fresh table that lacks it:
// Build Date (computed), Run ID (retired), company_clean (cleaning lives on Company itself),
// Score / Similarity / Valid / Start Date / Redirect Domain / Update Date (CSV noise, banned),
// State Full folds into State (full name wins), Source maps to Contact Source (provenance).
const BAN=['Build Date','Run ID','company_clean','Score','Similarity','Valid','Start Date','Redirect Domain','Update Date','MV'];
return $input.all().map(i => { const j = { ...i.json };
  if(j['State Full']!==undefined){ if(String(j['State Full']||'').trim()) j['State']=j['State Full']; delete j['State Full']; }
  if(Object.prototype.hasOwnProperty.call(j,'Source')){ if(j['Contact Source']===undefined) j['Contact Source']=j.Source; delete j.Source; }
  for(const k of BAN) delete j[k];
  return { json: j }; });

const sd = $getWorkflowStaticData('global');
